Set retStr = ""
Try {

	Set createDeployCls = ##class(IHC.ITF.SrcCtrlPkg.CreateDeploymentFiles).%New()
	Set retStr = createDeployCls.CreateDeploymentFiles(comp, nmSp, $GET(%session.Data("UsNm")), $GET(%session.Data("svnPsWd")) )

