Set retStr = ""
Set verStr = ""
Try {

	Set comp = $ZSTRIP(comp,"<>WC")

	Set createDeployCls = ##class(IHC.ITF.SrcCtrlPkg.CreateDeploymentFiles).%New()
	Set verStr = createDeployCls.GetVersions(comp, $GET(%session.Data("UsNm")), $GET(%session.Data("svnPsWd")), 1 )
	If ($LENGTH(verStr) <= 0)
	{
		Set retStr = "Could not find Deployment files for " _ comp
	}
	Else
	{

		Set retStr = "<BR><B> Last Ensemble Deployment:</B><BR><BR><table border=""1"">"
		Set retStr = retStr _ "<TR><TH>Env</TH><TH>Revision # </TH><TH>Impl Date </TH> <TH>Impl File </TH></TR>"
		Set retStr = retStr _ "<TR><TD>PROD </TD> " _ ..GetDeployments(comp, nmSp, "PROD")
		Set retStr = retStr _ "</TR><TR><TD>UAT  </TD> " _ ..GetDeployments(comp, nmSp, "UAT")
		Set retStr = retStr _ "</TR><TR><TD>QA   </TD> " _ ..GetDeployments(comp, nmSp, "QA")
		Set retStr = retStr _ "</TR></Table><BR><BR><B> Subversion check-ins: </B><BR><BR>"
		Set retStr = retStr _ verStr
		If ( $FIND(retStr, "Last Changed Rev") > 0)
		{
			Set retStr = $REPLACE(retStr, "Last Changed Rev", "<B>Last Changed Rev</B>", 0, 1, 1)
		}
		If ( $FIND(retStr, "Commited by") > 0)
		{
			Set retStr = $REPLACE(retStr, "Commited by", "<B><I>Commited by</I></B>", 0, 1, 1)
		}

	}


} Catch(err)
{
	Set retStr = "Exception: Could not find Deployment files " _ err.Data _" - " _ comp _ ", " _ verStr
}

Return retStr


