Set userName = $GET(%session.Data("UsNm"))
Set retStr = ""
Set sysEnv = $ZCONVERT($SYSTEM, "U")
If ( $FIND(sysEnv, "PRD") > 0)
{
	Set env = "PROD"
}
ElseIf ( $FIND(sysEnv, "UAT") > 0)
{
	Set env = "UAT"
}
ElseIf ( $FIND(sysEnv, "QA") > 0)
{
	Set env = "QA"
}
Else
{
	Set env = "DEV"
}

Set irisUtilCls = ##class(IHC.EAI.Security.IrisUtil).%New()
Set canDeploy = irisUtilCls.CheckDeployPrivileges(userName)

If (env = "UAT" &&  'canDeploy)
{
	Set retStr = "You do not have permission to deploy in UAT!"
	Quit retStr
}

Try {
	Set comp = $ZSTRIP(comp,"<>WC")
	Set deployCls = ##class(IHC.ITF.SrcCtrlPkg.DeployFilesToNamespace).%New()
	Set retStr = deployCls.DeployFile(comp, deployType , nmSp , $GET(%session.Data("UsNm")), $GET(%session.Data("svnPsWd")), revNum, env, depCls,  depConf, changeCls)
	If (updateSettings = 1)
	{
		Set crFl =  ##class(IHC.ITF.SrcCtrlPkg.CreateSettingFiles).%New()
		Set stat = crFl.updateSettings(nmSp, comp, env, $GET(%session.Data("UsNm")), $GET(%session.Data("svnPsWd")), settingRev, .statStr)
		Set retStr = retStr _ "; Update setting output: " _ statStr
	}
	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm($GET(%session.Data("UsNm")), "After Depoyment and Update Settings: " _ retStr)
} Catch(err)
{
	Set retStr = "Exception: CallDeployService Could not deploy files " _ err.Data
}
Return retStr

Set userName = $GET(%session.Data("UsNm"))
Set retStr = ""
Set sysEnv = $ZCONVERT($SYSTEM, "U")
If ( $FIND(sysEnv, "PRD") > 0)
{
	Set env = "PROD"
}
ElseIf ( $FIND(sysEnv, "UAT") > 0)
{
	Set env = "UAT"
}
ElseIf ( $FIND(sysEnv, "QA") > 0)
{
	Set env = "QA"
}
Else
{
	Set env = "DEV"
}

Set irisUtilCls = ##class(IHC.EAI.Security.IrisUtil).%New()
Set canDeploy = irisUtilCls.CheckDeployPrivileges(userName)

If (env = "UAT" &&  'canDeploy)
{
	Set retStr = "You do not have permission to deploy in UAT!" 
	Quit retStr
}

Try {
	If (depPkgAikbNum '= "")
	{
		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm($GET(%session.Data("UsNm")), "Call ParseDeploymentPackage")
		Set deployCls = ##class(IHC.ITF.SrcCtrlPkg.DeployFilesToNamespace).%New()
		Set stat =  deployCls.ParseDeploymentPackage(depPkgAikbNum, $GET(%session.Data("UsNm")), $GET(%session.Data("svnPsWd")), env, .retStr)
		If $$$ISOK(stat)
		{
			Set retStr = "<B>Status: OK</B>;; " _ retStr
			Set retStr = $REPLACE(retStr, ";", "<br/>")
		}
		Else
		{

			Set retStr = "<B>Failed</B>; Details: " _ %objlasterror _ "; " _retStr
		}
	}
	Else
	{
		Set retStr = "Deploy filename is NULL"
	}

} Catch(err)
{
	Set retStr = "Exception: CalldepPkgAikbNum Could not deploy files " _ err.Data
}

Set ..%GetComponentById("lblAccess").content = retStr
Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm($GET(%session.Data("UsNm")), "ParseDeploymentPackage set status to: " _ stat _ "; " _ retStr)

