		Set comment = 0
		Do file.MoveTo(0)

		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( rLen _ " < " _ fileSize)

		While ( rLen < fileSize)
		{
			Set len = 1024
			Set str = file.ReadLine(.len, .sc, .eol)

			Set rLen = rLen + len
			If ($LENGTH(str) > 0)
			{

				If ( (str [ "Deployment Package AIKB") && (comment = 1))
				{
					Set comment = 0
				}

				If ( (str [ searchcompNm) || (comment = 1))
				{
					Do wFile.WriteLine("#" _str)
					Set comment = 1
				}
				Else
				{
					Do wFile.WriteLine(str)
				}
			}
			If ( ($$$ISERR(sc)) || (eol = 1) || (len <= 0))
			{
			    Quit
			}

		}
		Do wFile.Close()
		Do file.Close()
		Do ##class(%File).CopyFile(wFileNm, fileNm, 1)
		Do ##class(%File).Delete(wFileNm)
	}
	Else
